using Microsoft.AspNetCore.Mvc;
using PmtAdmin.Infrastructure.Services;
using System.ComponentModel;
using System.Net;

namespace PmtAdmin.Api.Controllers
{
    [Route("api/[controller]")]
    [ApiController]
    public class JiraImportController : ControllerBase
    {
        private readonly IJiraService _jiraService;
        public JiraImportController(IJiraService jiraService)
        {
            _jiraService = jiraService;
        }

        [HttpGet("import/{baseUrl}/{token}/{projectIdOrKey}")]
        public async Task<IActionResult> ImportProject(
[DefaultValue("https://api.atlassian.com/ex/jira/a81196bb-9be1-4d9b-9c5b-31da7e7ec760")] string baseUrl,
    [DefaultValue("eyJraWQiOiJhdXRoLmF0bGFzc2lhbi5jb20tQUNDRVNTLTk0ZTczYTkwLTUxYWQtNGFjMS1hOWFjLWU4NGUwNDVjNDU3ZCIsImFsZyI6IlJTMjU2In0..AnmlbYnM3Fpd_kJvOVN-0f7qKwo19yrGDglwhbp_kmJQrbtgZBbhRwlpDc45EFCdGq65kob9sesp4W6HvKtI0hMq1xRmx7wQncJfo5zjNxo27MCUgbIs-ekaR1tcBItpPjHpNDRDw9wf2lPUxvdDe6afS3Ds2vP5LLVgCbu79JB55YjniEZwfzdt5dJCZ36PVGM3CXAvXTUxw_Kyh9Zq_3ag8JTZrTVwsB6u50Tx1Tpc9h80owog5K4_RT2P_69c9rFbN2pK4x7gbdYwgXJoTqHBPfO-s3GoBpamUMbiSQCuKqDldDBqquHZ7timzXLIm6SMZS8P_kU6One1Aul79g")] string token, [DefaultValue(463)] int projectIdOrKey
)
        {
            string decodedUrl = WebUtility.UrlDecode(baseUrl);
            var project = await _jiraService.GetSprintsByBoardIdAsync(decodedUrl, token, projectIdOrKey);
            return Ok(project);
        }
    }
}
